<main class="portal-shell hq-reports">
<header class="reports-heading"><div><span class="reports-eyebrow"><?= $esc($user['RoleName']) ?> / Reports</span><h1><?= $scope&&$scope['role']==='Physician'&&!$scope['main']?'My Reports':'Reports & Analytics' ?></h1><p>A clear view of visits, queues, and patient experience.</p></div><?php if($scope&&!$error): ?><a class="btn btn-primary" href="?<?= $esc(http_build_query(array_merge($_GET,['export'=>'csv']))) ?>">Export CSV</a><?php endif; ?></header>
