<?php if(($scope['role']==='Admin'||$scope['role']==='Staff'||$scope['main'])&&!($scope['role']==='Physician'&&$scope['view']==='ai')): $q=$pdo->prepare("SELECT u.UserID,u.FirstName,u.LastName,c.ClinicName FROM Users u JOIN Roles r ON r.RoleID=u.RoleID JOIN Clinic c ON c.ClinicID=u.ClinicID WHERE r.RoleName='Physician'".($scope['role']==='Admin'?'':' AND u.ClinicID=?').' ORDER BY u.FirstName,u.LastName');$q->execute($scope['role']==='Admin'?[]:[$scope['clinic']]); ?><label>Physician<select name="physician"><option value="0">All physicians</option><?php foreach($q->fetchAll() as $p): ?><option value="<?= (int)$p['UserID'] ?>" <?= $scope['physician']==$p['UserID']?'selected':'' ?>>Dr. <?= $esc($p['FirstName'].' '.$p['LastName'].($scope['role']==='Admin'?' Â· '.$p['ClinicName']:'')) ?></option><?php endforeach; ?></select></label><?php endif; ?><button class="btn btn-primary">Apply filters</button><a href="?view=<?= $esc($scope['view']) ?>">Reset</a></form>
<?php
$metric=[];
if($scope['view']==='performance'){$total=array_sum(array_column($rows,'Bookings'));$done=array_sum(array_column($rows,'Completed'));$metric=['Bookings'=>$total,'Completed'=>$done,'Completion rate'=>$total?round(100*$done/$total,1).'%':'â€”','Cancelled / no-show'=>array_sum(array_column($rows,'Cancelled')).' / '.array_sum(array_column($rows,'No-show'))];}
elseif($scope['view']==='queue'){$samples=array_sum(array_column($rows,'Wait samples'));$metric=['Queue entries'=>array_sum(array_column($rows,'Queue entries')),'Called'=>array_sum(array_column($rows,'Called')),'Measured wait samples'=>$samples];}
elseif($scope['view']==='ratings'){[$rw,$ra]=reportWhere($scope);$rq=$pdo->prepare("SELECT COUNT(*) AS n,AVG(f.Rating) AS average FROM Feedback f JOIN Appointments a ON a.AppointmentID=f.AppointmentID WHERE $rw");$rq->execute($ra);$ratingTotal=$rq->fetch();$metric=['Visit ratings'=>$ratingTotal['n'],'Average rating'=>$ratingTotal['n']?number_format($ratingTotal['average'],2).' / 5':'?'];}
else{$n=array_sum(array_column($rows,'Reference words'));$edits=array_sum(array_column($rows,'Substitutions'))+array_sum(array_column($rows,'Deletions'))+array_sum(array_column($rows,'Insertions'));$metric=['Evaluated recordings'=>count($rows),'Reference words'=>$n,'Word error rate'=>$n?number_format(100*$edits/$n,2).'%':'Not evaluated'];}
