<?php if($scope['view']==='queue'): ?><p class="reports-caption">Wait measures recorded arrival to first call. Missing or invalid timestamps are excluded. Historical call timestamps count calls but do not establish first-call wait.</p><?php
[$w,$a]=reportWhere($scope);$q=$pdo->prepare("SELECT HOUR(COALESCE(q.FirstCalledAt,q.CalledAt)) AS hour,COUNT(*) AS calls FROM Appointments a JOIN Queue q ON q.QueueID=(SELECT MAX(x.QueueID) FROM Queue x WHERE x.AppointmentID=a.AppointmentID) WHERE $w AND COALESCE(q.FirstCalledAt,q.CalledAt) IS NOT NULL GROUP BY hour ORDER BY calls DESC,hour LIMIT 1");$q->execute($a);$peak=$q->fetch(); ?><p>Busiest recorded call hour: <strong><?= $peak?$esc(sprintf('%02d:00â€“%02d:59 (%d calls)',$peak['hour'],$peak['hour'],$peak['calls'])):'No calls recorded' ?></strong></p><?php endif; ?>
<?php if($scope['view']==='ratings'): [$w,$a]=reportWhere($scope);$q=$pdo->prepare("SELECT f.Comment,f.Rating,CONCAT('Dr. ',u.FirstName,' ',u.LastName) AS Physician FROM Feedback f JOIN Appointments a ON a.AppointmentID=f.AppointmentID JOIN Users u ON u.UserID=a.PhysicianID WHERE $w AND TRIM(COALESCE(f.Comment,''))<>'' ORDER BY f.CreatedAt DESC LIMIT 10");$q->execute($a);foreach($q->fetchAll() as $comment): ?><blockquote><strong><?= $esc($comment['Physician']) ?> Â· <?= (int)$comment['Rating'] ?>/5</strong><p><?= $esc($comment['Comment']) ?></p></blockquote><?php endforeach; ?><p class="reports-caption">Ratings describe the overall visit experience; they are not a clinical assessment of the physician.</p><?php endif; ?></section>
<?php if($scope['view']==='ai'&&$scope['role']==='Physician'): $q=$pdo->prepare("SELECT t.TranscriptVersionID,t.GeneratedAt FROM AITranscriptVersions t JOIN Consultations c ON c.ConsultationID=t.ConsultationID WHERE c.DoctorID=? AND c.ClinicID=? AND t.TranscriptType='Original_STT' ORDER BY t.GeneratedAt DESC LIMIT 100");$q->execute([$scope['id'],$scope['clinic']]);$sources=$q->fetchAll(); ?>
<section class="reports-card"><h2>Evaluate a transcription</h2><?php if(!empty($_SESSION['report_saved'])): unset($_SESSION['report_saved']); ?><p role="status">Evaluation saved.</p><?php endif; ?><p>Use a reference you checked against the recording. Updating a sample replaces its existing evaluation.</p><?php if(!$sources): ?><p>No original recordings with transcripts are available for your consultations.</p><?php else: ?><form method="post" class="reports-evaluation"><input type="hidden" name="csrf_token" value="<?= $esc(csrfToken()) ?>"><label>Original transcript<select name="source" required><?php foreach($sources as $source): ?><option value="<?= (int)$source['TranscriptVersionID'] ?>">Source #<?= (int)$source['TranscriptVersionID'] ?> Â· <?= $esc($source['GeneratedAt']) ?></option><?php endforeach; ?></select></label><label>Language<select name="language"><?php foreach(['English','Filipino','Cebuano','Mixed','Other'] as $l): ?><option><?= $l ?></option><?php endforeach; ?></select></label><label>Verified reference transcript<textarea name="reference" required maxlength="20000" rows="6"></textarea></label><label class="reports-check"><input type="checkbox" name="verified" value="1" required> I verified this reference against the recording.</label><p class="reports-caption">Up to 1,500 words. Comparison ignores punctuation and letter case; substitutions, deletions, and insertions count as word errors. Reference text remains restricted to the assigned physician.</p><button class="btn btn-primary">Save evaluation</button></form><?php endif; ?></section><?php endif; endif; ?></main><?php require __DIR__.'/footer.php'; ?>
